      'x': { pieces: ['LogPile'], rotate: 'run', kind: 'cover' },
      'c': { pieces: ['Crate'], rotate: 'random90', h: 1, stack: { piece: 'Bundle', chance: 0.3, h: 0.62 }, kind: 'cover' },
      't': { pieces: ['Pine_A', 'Pine_B', 'Pine_C'], rotate: 'random90', kind: 'cover' },
